(()=>{const key='dat-portfolio:visited-vn:v1',boxes=[...document.querySelectorAll('.province-check input')],valid=new Set(boxes.map(b=>b.value));let visited=new Set();const note=document.getElementById('visited-storage-note');try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))visited=new Set(saved.filter(id=>valid.has(id)));}catch{note.textContent='Trình duyệt không cho phép lưu. Dấu tích chỉ giữ trong lần mở này.';}function render(){boxes.forEach(b=>b.checked=visited.has(b.value));document.querySelectorAll('[data-province]').forEach(marker=>{const show=visited.has(marker.dataset.province);marker.classList.toggle('is-visited',show);marker.setAttribute('aria-hidden',String(!show));if(marker.matches('[role=button]'))marker.setAttribute('tabindex',show?'0':'-1');});document.getElementById('visited-count').textContent=visited.size+' / '+boxes.length;const bar=document.querySelector('.visited-progress');bar.setAttribute('aria-valuenow',visited.size);bar.firstElementChild.style.width=(visited.size/boxes.length*100)+'%';}boxes.forEach(b=>b.addEventListener('change',()=>{b.checked?visited.add(b.value):visited.delete(b.value);render();try{localStorage.setItem(key,JSON.stringify([...visited]));}catch{note.textContent='Không lưu được trên trình duyệt. Dấu tích chỉ giữ trong lần mở này.';}}));const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();document.getElementById('province-search').addEventListener('input',e=>{const query=normalize(e.target.value.trim());let shown=0;boxes.forEach(b=>{const row=b.closest('label');row.hidden=!normalize(row.textContent).includes(query);if(!row.hidden)shown++;});document.querySelector('.province-no-results').hidden=shown>0;});window.addEventListener('storage',e=>{if(e.key!==key)return;try{const ids=JSON.parse(e.newValue||'[]');if(Array.isArray(ids)){visited=new Set(ids.filter(id=>valid.has(id)));render();}}catch{}});render();})();